/* ============================================================
   script.min.js — ванильный JS сайта «Казачья Воля»
   1) Бургер-меню (мобильная навигация)
   2) Ленивая загрузка картинок (IntersectionObserver + нативный loading="lazy")
   3) Плавное появление блоков при прокрутке
   Без внешних библиотек. Работает во всех современных браузерах.
   ============================================================ */
(function () {
  'use strict';

  /* ---------- 1. БУРГЕР-МЕНЮ (+ затемняющий оверлей) ---------- */
  var burger = document.getElementById('burger');
  var nav = document.getElementById('nav');
  var overlay = document.getElementById('navOverlay');

  function setMenu(open) {
    if (!nav) return;
    nav.classList.toggle('is-open', open);
    if (overlay) overlay.classList.toggle('is-open', open);
    burger.setAttribute('aria-expanded', open ? 'true' : 'false');
    burger.setAttribute('aria-label', open ? 'Закрыть меню' : 'Открыть меню');
    document.body.style.overflow = open ? 'hidden' : '';
  }

  if (burger && nav) {
    burger.addEventListener('click', function () {
      setMenu(!nav.classList.contains('is-open'));
    });
    if (overlay) overlay.addEventListener('click', function () { setMenu(false); });

    // Закрытие по клику на ссылку (чтобы меню не «липло» после перехода)
    nav.addEventListener('click', function (e) {
      if (e.target.closest('a')) setMenu(false);
    });

    // Закрытие по клавише Escape — забота о доступности
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && nav.classList.contains('is-open')) {
        setMenu(false);
        burger.focus();
      }
    });
  }

  /* ---------- 1b. ТЕНЬ ШАПКИ ПРИ ПРОКРУТКЕ ---------- */
  var header = document.querySelector('.site-header');
  if (header) {
    var onScroll = function () {
      header.classList.toggle('is-scrolled', window.scrollY > 8);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
  }

  /* ---------- 2. ЛЕНИВАЯ ЗАГРУЗКА ИЗОБРАЖЕНИЙ ----------
     Картинки с data-src подгружаются только когда попадают в область
     видимости. Обычные <img loading="lazy"> браузер грузит сам. */
  var lazyImages = [].slice.call(document.querySelectorAll('img[data-src]'));

  if ('IntersectionObserver' in window && lazyImages.length) {
    var lazyObserver = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        var img = entry.target;
        img.src = img.getAttribute('data-src');
        if (img.getAttribute('data-srcset')) img.srcset = img.getAttribute('data-srcset');
        img.addEventListener('load', function () { img.classList.add('is-loaded'); });
        obs.unobserve(img);
      });
    }, { rootMargin: '200px 0px' }); // начинаем грузить заранее — за 200px до появления

    lazyImages.forEach(function (img) { lazyObserver.observe(img); });
  } else {
    // Фолбэк для старых браузеров — грузим всё сразу
    lazyImages.forEach(function (img) { img.src = img.getAttribute('data-src'); });
  }

  /* ---------- 3. ПОЯВЛЕНИЕ БЛОКОВ ПРИ ПРОСКРУТКЕ ---------- */
  var sections = [].slice.call(
    document.querySelectorAll('.section, .hero, .event-card, .news-card')
  );
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  if ('IntersectionObserver' in window && sections.length && !reduceMotion) {
    var revealObserver = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          obs.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12 });

    sections.forEach(function (el) {
      el.classList.add('reveal-init');
      revealObserver.observe(el);
    });
  }
})();
